import fs from 'node:fs';

function read(path) { return fs.readFileSync(path, 'utf8'); }
function write(path, content) { fs.mkdirSync(path.split('/').slice(0, -1).join('/'), { recursive: true }); fs.writeFileSync(path, content); }
function replaceOnce(path, before, after) {
  const source = read(path);
  const count = source.split(before).length - 1;
  if (count !== 1) throw new Error(`${path}: expected one marker, found ${count}: ${before.slice(0, 100)}`);
  write(path, source.replace(before, after));
}
function appendOnce(path, marker, content) {
  const source = read(path);
  if (source.includes(marker)) return;
  write(path, `${source.trimEnd()}\n\n${content.trim()}\n`);
}

const sharedPath = 'packages/shared/src/index.ts';
replaceOnce(sharedPath,
`export type WorldProject = {\n  projectId: string;`,
`export type EnrichmentArtifactAuthority = 'authoritative' | 'derived' | 'presentation';\n\nexport type EnrichmentNodeRunRecord = {\n  nodeId: string;\n  stageId: string;\n  implementationId: string;\n  version: string;\n  dependencies: string[];\n  outputs: string[];\n  startedAt: string;\n  completedAt: string;\n  durationMs: number;\n  validation?: {\n    valid: boolean;\n    issues: Array<{ severity: 'error' | 'warning'; message: string }>;\n  };\n};\n\nexport type OrbitalPresentationBody = {\n  id: string;\n  parentBodyId: string | null;\n  kind: SystemBody['bodyType'] | 'moon';\n  orbitalOrder: number;\n  semiMajorAxisAu: number | null;\n  semiMajorAxisParentRadii: number | null;\n  eccentricity: number;\n  inclinationDeg: number;\n  longitudeAscendingNodeDeg: number;\n  argumentOfPeriapsisDeg: number;\n  orbitalPeriodDays: number;\n  phaseAtEpochRad: number;\n  rotationPeriodHours: number;\n  axialTiltDeg: number;\n  sizeClass: number;\n  massClass: number;\n  visibleFromPrimary: boolean;\n  placeholder: boolean;\n};\n\nexport type SystemOrbitalContextArtifact = {\n  artifactKey: 'project.system-orbital-context';\n  artifactVersion: 1;\n  artifactRole: 'presentation';\n  status: 'complete';\n  workflow: {\n    id: 'project.system-orbital-context';\n    version: '1.0.0';\n    graphSignature: string;\n    nodes: EnrichmentNodeRunRecord[];\n  };\n  source: {\n    projectId: string;\n    worldId: string;\n    sourceSignature: string;\n    generatorVersion: string;\n    appVersion: string;\n    sourceCommit?: string;\n  };\n  seed: string;\n  epochIso: string;\n  startedAt: string;\n  completedAt: string;\n  totalMs: number;\n  artifactSignature: string;\n  validation: {\n    valid: boolean;\n    issues: Array<{ severity: 'error' | 'warning'; message: string }>;\n  };\n  payload: {\n    modelVersion: 'system-orbital-context-v1';\n    star: {\n      id: string;\n      massSolar: number;\n      radiusSolar: number;\n      luminositySolar: number;\n      effectiveTemperatureK: number;\n      colorHex: string;\n    };\n    primaryBodyId: string;\n    visibleBodyIds: string[];\n    bodies: OrbitalPresentationBody[];\n  };\n};\n\nexport type ProjectEnrichmentArtifact = SystemOrbitalContextArtifact;\nexport type ProjectEnrichmentArtifacts = Record<string, ProjectEnrichmentArtifact>;\n\nexport type WorldProject = {\n  projectId: string;`);

